  wire [9:0] hw_bias;

  tc_rsync u_rsync (
    .clk      (clk),
    .nrst_in  (rst_n),
    .nrst_out (nrst)
  );

  tc_dsync u_mode (
    .clk  (clk),
    .nrst (nrst),
    .din  (mode),
    .dout (mode_s)
  );

  tc_wrom u_wrom (
    .i    (idx_i),
    .j    (idx_j),
    .c    (idx_c),
    .bc   (idx_bc),
    .w1   (hw_w1),
    .w2   (hw_w2),
    .th   (hw_th),
    .bias (hw_bias)
  );

  tc_core #(
    .NI_LAST (6'd63),
    .H_LAST  (6'd47),
    .C_LAST  (4'd9)
  ) u_core (
    .clk       (clk),
    .rst_n     (nrst),
    .cs_n      (cs_n),
    .mode_s    (mode_s),
    .din       (din),
    .hw_w1     (hw_w1),
    .hw_w2     (hw_w2),
    .hw_th     (hw_th),
    .hw_bias   (hw_bias),
    .idx_i     (idx_i),
    .idx_j     (idx_j),
    .idx_c     (idx_c),
    .idx_bc    (idx_bc),
    .busy      (busy),
    .result    (result),
    .score     (score),
    .score_tgl (score_tgl)
  );

endmodule
